def _get_lock_filename(self, filename: str) -> str:
    """Return the lock file name for *filename*."""
    directory, basename = os.path.split(filename)
    return os.path.join(directory, f".{basename}.lock")

def _create_lock_file(self, filename: str) -> str:
    """Atomically create and return the lock file for *filename*."""
    lock_filename = self._get_lock_filename(filename)
    content = (
        f"PID: {os.getpid()}\n"
        f"Time: {datetime.datetime.now().isoformat()}\n"
    ).encode("utf-8")

    try:
        fd = os.open(lock_filename, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    except FileExistsError as e:
        raise ClickException(
            _("File is already being edited: {filename}").format(filename=filename)
        ) from e

    try:
        with os.fdopen(fd, "wb") as f:
            f.write(content)
    except BaseException:
        # Do not leave a partially written lock behind.
        self._remove_lock_file(lock_filename)
        raise

    return lock_filename

def _remove_lock_file(self, lock_filename: str) -> None:
    """Remove a lock file, ignoring a lock that is already gone."""
    try:
        os.unlink(lock_filename)
    except FileNotFoundError:
        pass

