def _adjust_palette_lightness(self, lightness_factor):
    """Adjust the lightness of this palette image's colors."""
    if lightness_factor == 1.0:
        return

    palette = self.palette.palette
    channels = len(self.palette.mode)
    adjusted = bytearray(palette)
    for index in range(0, len(adjusted), channels):
        for channel in range(min(3, channels)):
            adjusted[index + channel] = min(
                255, int(adjusted[index + channel] * lightness_factor)
            )
    self.palette.palette = adjusted
    self.palette.dirty = 1

